package com.petlis.service.impl;
import com.petlis.common.exception.BusinessException;import org.junit.jupiter.api.Test;import java.util.*;import java.io.ByteArrayInputStream;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import static org.junit.jupiter.api.Assertions.*;
class LegacyOrderExportWorkbookTest {
 @Test void cityHierarchyRetainsMissingParentPrefixAndRejectsCycles(){var cities=new HashMap<Long,Map<String,Object>>();cities.put(1L,Map.of("CityName","省","BelongCity_cityId",0));cities.put(2L,Map.of("CityName","市","BelongCity_cityId",1));assertEquals("省/市",LegacyOrderExportWorkbook.cityName(2,cities));assertEquals("-",LegacyOrderExportWorkbook.cityName(0,cities));cities.put(3L,Map.of("CityName","区","BelongCity_cityId",99));assertEquals("-/区",LegacyOrderExportWorkbook.cityName(3,cities));cities.put(1L,Map.of("CityName","循环","BelongCity_cityId",2));assertEquals(409,assertThrows(BusinessException.class,()->LegacyOrderExportWorkbook.cityName(2,cities)).getCode());}
 @Test void originalCapIsExplicitAndNullPaymentIsNotInvented()throws Exception{try(var workbook=new XSSFWorkbook(new ByteArrayInputStream(LegacyOrderExportWorkbook.write(List.of(Map.of("TestPrice","12.50","IsCheckPass",0)),Map.of(),10001,null)))){assertEquals("",workbook.getSheetAt(0).getRow(1).getCell(24).getStringCellValue());assertEquals("是，请按条件分批导出",workbook.getSheet("导出说明").getRow(4).getCell(1).getStringCellValue());assertEquals("10001",workbook.getSheet("导出说明").getRow(1).getCell(1).getStringCellValue());}}
}
